CREATE TABLE partner_feed (external_ref TEXT NOT NULL, account_id INTEGER NOT NULL, amount_cents INTEGER NOT NULL, posted_at TEXT NOT NULL);
INSERT INTO partner_feed SELECT 'EXT-' || transaction_id, account_id, amount_cents, posted_at FROM transactions WHERE transaction_type = 'payroll' AND account_id <= 60;
INSERT INTO partner_feed SELECT * FROM partner_feed WHERE CAST(substr(external_ref, 5) AS INTEGER) % 7 = 0;
CREATE TABLE partner_ledger (external_ref TEXT PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(account_id), amount_cents INTEGER NOT NULL, posted_at TEXT NOT NULL);
